"""Demo 1: build the Eulerian triangle and the row polynomials of its square."""
from __future__ import annotations
from typing import List

def eulerian(n: int, k: int) -> int:
    if n == 0:
        return 1 if k == 0 else 0
    if k < 0 or k > n - 1:
        return 0
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def squared_poly_coeffs(n: int) -> List[int]:
    coeffs = [sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))
              for k in range(n + 1)]
    while len(coeffs) > 1 and coeffs[-1] == 0:
        coeffs.pop()
    return coeffs

if __name__ == "__main__":
    for n in range(8):
        print(f"B_{n} coeffs (low->high): {squared_poly_coeffs(n)}")

"""Demo 2: certify real-rootedness of B_n by integer sign-change bracketing.

A polynomial of degree m with m distinct real roots must split (saturation
principle).  Each unit interval across which B_n changes sign contains a real
root by the Intermediate Value Theorem, so deg-many sign changes = a proof.
"""
from __future__ import annotations
from typing import List

def eulerian(n: int, k: int) -> int:
    if n == 0:
        return 1 if k == 0 else 0
    if k < 0 or k > n - 1:
        return 0
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def coeffs(n: int) -> List[int]:
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))
         for k in range(n + 1)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

def peval(c: List[int], x: float) -> float:
    acc = 0.0
    for a in reversed(c):
        acc = acc * x + a
    return acc

def certify(n: int, lo: int = -1000) -> bool:
    c = coeffs(n)
    deg = len(c) - 1
    changes = sum(1 for a in range(lo, 1)
                  if peval(c, a) == 0 or peval(c, a) * peval(c, a + 1) < 0)
    return changes == deg

if __name__ == "__main__":
    for n in range(8):
        print(f"n={n}: certified real-rooted by integer brackets? {certify(n)}")

"""Demo 3: the boundary at n=8 -- two roots crowd into (-1, 0).

Integer brackets certify real-rootedness for n <= 7 but fail at n = 8, where
two roots share a single unit interval.  Finer brackets reveal both.
"""
from __future__ import annotations
from typing import List

def eulerian(n: int, k: int) -> int:
    if n == 0:
        return 1 if k == 0 else 0
    if k < 0 or k > n - 1:
        return 0
    return (k + 1) * eulerian(n - 1, k) + (n - k) * eulerian(n - 1, k - 1)

def coeffs(n: int) -> List[int]:
    c = [sum(eulerian(n, j) * eulerian(j, k) for j in range(n + 1))
         for k in range(n + 1)]
    while len(c) > 1 and c[-1] == 0:
        c.pop()
    return c

def peval(c: List[int], x: float) -> float:
    acc = 0.0
    for a in reversed(c):
        acc = acc * x + a
    return acc

def bisect(c: List[int], a: float, b: float) -> float:
    fa = peval(c, a)
    for _ in range(200):
        m = 0.5 * (a + b)
        if fa * peval(c, m) <= 0:
            b = m
        else:
            a, fa = m, peval(c, m)
    return 0.5 * (a + b)

if __name__ == "__main__":
    c = coeffs(8)
    print("B_8 coeffs:", c)
    roots = []
    N = 2000
    for i in range(N):
        x0, x1 = -400 + 400 * i / N, -400 + 400 * (i + 1) / N
        if peval(c, x0) * peval(c, x1) < 0:
            roots.append(round(bisect(c, x0, x1), 5))
    print("all six roots:", roots)
    print("roots in (-1,0):", [r for r in roots if -1 < r < 0])

