function SQUARED_ROWS(tri):
  out <- []
  for n from 0 to len(tri)-1:
    c <- array of length n+1
    for k from 0 to n:
      c[k] <- sum over j in 0..n of A(n,j)*A(j,k)
    strip trailing zeros of c (keep at least one entry)
    append c to out
  return out

function CERTIFY_REAL_ROOTED(coeffs, lo):
  deg <- len(coeffs) - 1
  brackets <- []
  for a from lo to 0:
    va <- eval(coeffs, a); vb <- eval(coeffs, a+1)
    if va == 0: append (a,a) to brackets
    else if va*vb < 0: append (a,a+1) to brackets
  certified <- (len(brackets) == deg)
  return (certified, brackets)
